def system(record_id, subs, source_class, objects, modes, time, schema, authority, hazards, refs, **extra):
    out = {
        "record_id": record_id, "record_kind": "source_system_need", "edition": 1,
        "status": "sourced_candidate", "industry_id": INDUSTRY, "subindustry_ids": subs,
        "source_class": source_class, "objects": objects, "read_change_modes": modes,
        "time_order_finality": time, "schema_semantics": schema, "authority": authority,
        "hazards": hazards, "evidence_refs": refs,
    }
    out.update(extra)
    return out


