def make_case(group, spec):
    slug, name, question, action, modes, methods, output = spec
    operations = []
    failures = []
    for mode in modes:
        operations.extend(MODE_OPERATIONS.get(mode, []))
        failures.extend(MODE_FAILURES.get(mode, []))
    operations = list(dict.fromkeys(operations))
    failures = list(dict.fromkeys(failures))
    return {
        "record_id": f"energy.case.{slug}",
        "record_kind": "analytical_case",
        "edition": 1,
        "status": "sourced_candidate",
        "industry_id": INDUSTRY,
        "subindustry_ids": [group["sub"]],
        "name": name,
        "analytical_modes": modes,
        "sovereign_question": question,
        "decision_or_action": action,
        "actors": group["actors"],
        "unit_of_analysis": group["unit"],
        "population": f"All in-scope {group['unit']} under the declared asset, jurisdiction, purpose and study window.",
        "grain": group["grain"],
        "time_model": ["event/phenomenon time separate from ingest and approval time", "effective-dated asset/model/rule editions", "forecast or scenario issue time separate from valid time", "late corrections never overwrite prior evidence"],
        "source_system_refs": group["systems"],
        "data_shape_refs": group["shapes"],
        "data_type_refs": ["quantities carry dimension, unit, basis and uncertainty", "observations are distinct from estimates forecasts scenarios and decisions"],
        "method_refs": methods,
        "operation_refs": operations,
        "inputs": ["version-pinned governed observations from referenced data-shape contracts", "effective asset topology, operating state, limits and rule/model editions", "declared study population, exclusions, horizon, scenarios and decision loss"],
        "outputs": [output, "method/run receipt with data cutoff, assumptions, uncertainty, refusals and unresolved evidence", "action proposal explicitly separated from observation and authorized execution"],
        "assumptions": ["identity, units, reference conditions, coordinate/datum and time mappings are validated", "selection, censoring, missingness and measurement uncertainty are declared", "model structure and parameters are fit for the stated population and horizon"],
        "invariants": ["raw observations and prior revisions remain addressable", "scenario, estimate and forecast are never asserted as observed fact", "hard safety, legal, environmental and authority constraints cannot be softened by objective weights", "no action is executed without the named operational authority and a receipt"],
        "failure_modes": failures + ["source/model edition mismatch", "false precision from missing or biased observations", "output used outside validated operating regime"],
        "evidence_refs": group["evidence"],
        "llm_dependency": "prohibited_core",
        "limitations": ["Evidence supports the domain need and data/method family, not universal validity of one implementation.", "Site-specific physics, regulation, contracts, calibration and authority remain required.", "This candidate is not a safety-certified controller, regulatory determination or autonomous actuation contract."],
        "metric_only": False,
    }


CASES = [make_case(group, spec) for group in GROUPS for spec in group["cases"]]


def validate_local():
    ids = [r["record_id"] for r in SOURCES + SYSTEMS + SHAPES + CASES]
    dupes = [item for item, count in Counter(ids).items() if count > 1]
    if dupes:
        raise ValueError(f"duplicate ids: {dupes}")
    evidence_ids = {r["record_id"] for r in SOURCES}
    system_ids = {r["record_id"] for r in SYSTEMS}
    shape_ids = {r["record_id"] for r in SHAPES}
    for record in SYSTEMS + SHAPES + CASES:
        unknown = set(record["evidence_refs"]) - evidence_ids
        if unknown:
            raise ValueError(f"{record['record_id']} unknown evidence: {sorted(unknown)}")
    for record in CASES:
        unknown_systems = set(record["source_system_refs"]) - system_ids
        unknown_shapes = set(record["data_shape_refs"]) - shape_ids
        if unknown_systems or unknown_shapes:
            raise ValueError(f"{record['record_id']} unknown refs systems={unknown_systems} shapes={unknown_shapes}")
        if record.get("metric_only") is not False or not record["decision_or_action"]:
            raise ValueError(f"{record['record_id']} is not a decision case")
    if len(SOURCES) < 25:
        raise ValueError("family requires at least 25 sources")


def write_jsonl(name, records):
    path = ROOT / name
    with path.open("w", encoding="utf-8") as handle:
        for record in records:
            handle.write(json.dumps(record, ensure_ascii=False, separators=(",", ":")) + "\n")


def main():
    validate_local()
    write_jsonl("sources.jsonl", SOURCES)
    write_jsonl("source-systems.jsonl", SYSTEMS)
    write_jsonl("data-shapes.jsonl", SHAPES)
    write_jsonl("analytics-cases.jsonl", CASES)
    print(json.dumps({
        "sources": len(SOURCES), "source_system_needs": len(SYSTEMS),
        "data_shape_needs": len(SHAPES), "analytical_cases": len(CASES),
        "subindustries": len({g["sub"] for g in GROUPS}),
        "cases_by_subindustry": dict(sorted(Counter(c["subindustry_ids"][0] for c in CASES).items())),
        "cases_by_mode": dict(sorted(Counter(mode for c in CASES for mode in c["analytical_modes"]).items())),
    }, indent=2))


if __name__ == "__main__":
    main()
